PREFIX : <https://example.org/farmacos-aprobados/ontology#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?type (COUNT(DISTINCT ?drug) AS ?n)
WHERE {
  ?drug a :Drug ;
        :hasDrugType ?drug_type .
  ?drug_type rdfs:label ?type .
}
GROUP BY ?type
ORDER BY DESC(?n)
